using System.IO;
using Tiger.Schema;
using System.Runtime.Loader;
using Tiger;
using Tiger.Schema.Strings;
var dir=Environment.GetEnvironmentVariable("MIDA_DIR") ?? throw new Exception("Set MIDA_DIR to the MIDA distribution directory");
AssemblyLoadContext.Default.Resolving += (ctx,name) => { var p=Path.Combine(dir,name.Name+".dll"); return File.Exists(p) ? ctx.LoadFromAssemblyPath(p) : null; };
Directory.SetCurrentDirectory(dir);
Strategy.AddNewStrategy(TigerStrategy.MARATHON, Environment.GetEnvironmentVariable("MARATHON_PACKAGES") ?? throw new Exception("Set MARATHON_PACKAGES to the snapshot packages directory"), true);
SchemaDeserializer.Setup(); FileResourcer.Setup(); PackageResourcer.Setup(); Hash64Map.Setup();
if(args.Length>0 && args[0]=="typed") { var h=new FileHash("80B38569"); var t=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.S8080AB82>(h); Console.WriteLine($"parent={h} entityComponent={t.TagData.EntityComponent.Hash}"); var group=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.S8080B3EA>(new FileHash("80B38BEC")); var parents=group.TagData.EntityComponents.Where(x=>x.EntityComponentParent != null).Select(x=>x.EntityComponentParent.Hash.ToString()).ToList(); Console.WriteLine($"group=80B38BEC count={parents.Count} contains_parent={parents.Contains("80B38534")}"); var root=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.S8080B381>(new FileHash("80B38C23")); Console.WriteLine($"entry=80B38C23 link={root.TagData.Unk18.Hash}"); var activity=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.SActivity>(new FileHash("80B3808C")); var refs=activity.TagData.Unk50.SelectMany(e=>e.Unk18).Where(e=>e.UnkEntityReference!=null).Select(e=>e.UnkEntityReference.Hash.ToString()).ToList(); Console.WriteLine($"activity=80B3808C references={refs.Count} contains_entry={refs.Contains("80B38C23")}"); return; }
if(args.Length>0 && args[0]=="keygroup") {var group=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.S8080B3EA>(new FileHash("80B38BEC"));int examined=0,errors=0,groupHits=0;foreach(var e in group.TagData.EntityComponents){try{var parent=e.EntityComponentParent;if(parent==null||parent.TagData.EntityComponent==null)continue;var c=parent.TagData.EntityComponent;examined++;uint a=c.TagData.Unk10.ResourceClassHash,b=c.TagData.Unk18.ResourceClassHash;if(a==0x80B38561||b==0x80B38555){Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{group="80B38BEC",parent=parent.Hash.ToString(),component=c.Hash.ToString(),instance=a.ToString("X8"),definition=b.ToString("X8")}));groupHits++;}}catch(Exception ex){errors++;Console.Error.WriteLine(ex.GetType().Name+": "+ex.Message);}}Console.Error.WriteLine($"components={examined} errors={errors} groupHits={groupHits}");return;}

if(args.Length>0 && args[0]=="evidence") { foreach(var id in new[]{"80B38567","80B38531","80B3808C","80B38C23","80B38BEC","80B38569"}) {var h=new FileHash(id); var b=PackageResourcer.Get().GetFileData(h); var m=h.GetFileMetadata(); var matches=System.Text.RegularExpressions.Regex.Matches(System.Text.Encoding.Latin1.GetString(b),@"[ -~]{8,}").Select(x=>x.Value).Where(x=>x.Contains("vault_breaker",StringComparison.OrdinalIgnoreCase)); Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {tag=id,packageId=h.PackageId.ToString("X4"),index=h.FileIndex,reference=m.Reference.ToString(),size=b.Length,sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(b)),strings=matches.ToArray()})); } return; }

if(args.Length>0 && (args[0]=="scan-lua" || args[0]=="scan-lua-all")) { var map=PackageResourcer.Get().PackagePathsCache.GetAllPackagesMap().Where(x=>args[0]=="scan-lua-all" || x.Value.Contains("marathon_deck_001",StringComparison.OrdinalIgnoreCase)).OrderBy(x=>x.Key).ToList(); int examined=0, errors=0, oversized=0, matches=0; byte[] magic={0x1b,0x4c,0x75,0x61}; foreach(var pair in map) {var pkg=PackageResourcer.Get().GetPackage(pair.Key); foreach(var e in pkg.GetAllFileMetadata()) {if(args[0]=="scan-lua-all" && !(e.Type==8 || e.Type==16)) continue; if(e.Size>67108864){oversized++;continue;} try {var b=pkg.GetFileSpan(e.FileIndex); examined++; if(examined % 1000 == 0) Console.Error.WriteLine($"progress package={pair.Key:X4} examined={examined} errors={errors} matches={matches}"); int offset=b.IndexOf(magic); if(offset>=0){matches++;Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {tag=e.Hash.ToString(),package=Path.GetFileName(pair.Value),size=e.Size,offset}));}} catch(Exception ex){errors++;if(errors<=10)Console.Error.WriteLine($"FAILED {e.Hash}: {ex.GetType().Name}");}} Console.Error.WriteLine($"package={pair.Key:X4} examined={examined} errors={errors} matches={matches}"); } Console.Error.WriteLine($"TOTAL packages={map.Count} examined={examined} errors={errors} oversized={oversized} matches={matches}"); return; }

if(args.Length>0 && args[0]=="handle-types") { var map=Path.Combine(Directory.GetParent(Environment.GetEnvironmentVariable("MARATHON_PACKAGES")!)!.FullName,"handle_map_win64.bin"); var b=File.ReadAllBytes(map);int n=BitConverter.ToInt32(b,0);if(n<0 || b.Length!=8+10*n)throw new Exception("unexpected map layout");var counts=new SortedDictionary<string,int>();int errors=0;var reasons=new SortedDictionary<string,int>();var missing=new SortedDictionary<ushort,int>();var paths=PackageResourcer.Get().PackagePathsCache.GetAllPackagesMap(); for(int i=0;i<n;i++){int at=8+7*i;uint raw=BitConverter.ToUInt32(b,at);uint x=(uint)(b[at+4]|b[at+5]<<8|b[at+6]<<16);try{var m=new FileHash(raw).GetFileMetadata();string key=$"type={m.Type} subtype={m.SubType} first={(x==0xffffff?"sentinel":"index")}";counts.TryGetValue(key,out int count);counts[key]=count+1;}catch(Exception e){errors++;var pkg=new FileHash(raw).PackageId;if(!paths.ContainsKey(pkg)){missing.TryGetValue(pkg,out int q);missing[pkg]=q+1;}if(errors<=3)Console.Error.WriteLine($"ERROR_SAMPLE id={raw:X8} {e.GetType().Name}: {e.Message}");reasons.TryGetValue(e.GetType().Name,out int z);reasons[e.GetType().Name]=z+1;}}foreach(var c in counts)Console.WriteLine($"{c.Key} count={c.Value}");foreach(var k in missing)Console.Error.WriteLine($"MISSING_CACHE package={k.Key:X4} rows={k.Value}");foreach(var r in reasons)Console.Error.WriteLine($"ERROR {r.Key} count={r.Value}");Console.Error.WriteLine($"TOTAL rows={n} resolved={n-errors} errors={errors}");return;}

if(args.Length>0 && args[0]=="compiler-metadata") {var output=Environment.GetEnvironmentVariable("RE_OUTPUT") ?? throw new Exception("Set RE_OUTPUT");Directory.CreateDirectory(output);foreach(var id in new[]{"80A6A070","80A6A071","80A6A072","80B3DB5D","80B3DB5E","80B3DB5F","80B37C7E","80B38561","80B3B819"}) {var h=new FileHash(id);var b=PackageResourcer.Get().GetFileData(h);var path=Path.Combine(output,id+".bin");using(var f=new FileStream(path,FileMode.CreateNew))f.Write(b);var words=System.Text.RegularExpressions.Regex.Matches(System.Text.Encoding.Latin1.GetString(b),@"[ -~]{4,}").Select(m=>new {offset=m.Index,text=m.Value}).ToArray();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {tag=id,size=b.Length,sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(b)),strings=words}));}return;}

if(args.Length>0 && args[0]=="vault-reference-records") {var output=Environment.GetEnvironmentVariable("RE_OUTPUT") ?? throw new Exception("Set RE_OUTPUT");Directory.CreateDirectory(output);foreach(var id in new[]{"80B37FEB","80B37FEC","80B38562","80B3858E","80B37FED","80B38567"}) {var h=new FileHash(id);var b=PackageResourcer.Get().GetFileData(h);var path=Path.Combine(output,id+".bin");using(var f=new FileStream(path,FileMode.CreateNew))f.Write(b);var words=System.Text.RegularExpressions.Regex.Matches(System.Text.Encoding.Latin1.GetString(b),@"[ -~]{4,}").Select(m=>new {offset=m.Index,text=m.Value}).ToArray();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {tag=id,size=b.Length,sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(b)),strings=words}));}return;}

if(args.Length>1 && args[0]=="dump-tags") {var output=Environment.GetEnvironmentVariable("RE_OUTPUT") ?? throw new Exception("Set RE_OUTPUT");Directory.CreateDirectory(output);foreach(var id in args.Skip(1)) {if(id.Length!=8 || !uint.TryParse(id,System.Globalization.NumberStyles.HexNumber,null,out _))throw new Exception("bad tag");var h=new FileHash(id);var b=PackageResourcer.Get().GetFileData(h);var m=h.GetFileMetadata();var path=Path.Combine(output,id+".bin");using(var f=new FileStream(path,FileMode.CreateNew))f.Write(b);var words=System.Text.RegularExpressions.Regex.Matches(System.Text.Encoding.Latin1.GetString(b),@"[ -~]{4,}").Select(z=>new {offset=z.Index,text=z.Value}).ToArray();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new {tag=id,reference=m.Reference.ToString(),size=b.Length,sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(b)),strings=words}));}return;}

if(args.Length>0 && args[0]=="vault-names") {var h=new FileHash("80B37FEC");var t=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Entity.S8080B1E2>(h);var values=t.TagData.Unk08.Select(e=>e.Unk00.Value?.Name.Value).Where(v=>v!=null).ToArray();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{tag=h.ToString(),names=values}));return;}

if(args.Length>0 && args[0]=="vault-adjacent-metadata") {foreach(var center in new uint[]{0x80B37C7E,0x80B37FED,0x80B38561})for(int delta=-12;delta<=12;delta++){uint id=(uint)(center+delta);try{var h=new FileHash(id);var m=h.GetFileMetadata();Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{center=center.ToString("X8"),tag=id.ToString("X8"),reference=m.Reference.ToString(),type=m.Type,subtype=m.SubType,size=m.Size}));}catch(Exception ex){Console.Error.WriteLine($"FAILED {id:X8} {ex.GetType().Name}");}}return;}

if(args.Length>0 && args[0]=="group-components") {var group=FileResourcer.Get().GetSchemaTag<Tiger.Schema.Activity.MARATHON.S8080B3EA>(new FileHash("80B38BEC"));int seen=0,errors=0;foreach(var entry in group.TagData.EntityComponents){try{var parent=entry.EntityComponentParent;if(parent==null||parent.TagData.EntityComponent==null)continue;var c=parent.TagData.EntityComponent;uint a=c.TagData.Unk10.ResourceClassHash,b=c.TagData.Unk18.ResourceClassHash;var summaries=new List<object>();foreach(var id in new[]{a,b}){try{var h=new FileHash(id);var data=PackageResourcer.Get().GetFileData(h);var words=System.Text.RegularExpressions.Regex.Matches(System.Text.Encoding.Latin1.GetString(data),@"[ -~]{6,}").Select(m=>m.Value).Where(v=>v.Contains(".es",StringComparison.OrdinalIgnoreCase)||v.Contains(".bs",StringComparison.OrdinalIgnoreCase)||v.Contains("vault",StringComparison.OrdinalIgnoreCase)||v.Contains("incident",StringComparison.OrdinalIgnoreCase)).Take(30).ToArray();summaries.Add(new{tag=id.ToString("X8"),size=data.Length,words});}catch{summaries.Add(new{tag=id.ToString("X8"),unresolved=true});}}Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{parent=parent.Hash.ToString(),component=c.Hash.ToString(),classes=summaries}));seen++;}catch(Exception ex){errors++;if(errors<=5)Console.Error.WriteLine(ex.Message);}}Console.Error.WriteLine($"components={seen} errors={errors}");return;}
